INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133391, 'spa', 'Ciudad, urbe', 'Ciudad o urbe: sustantivo femenino arameo (קִרְיָה/קִרְיָא) cognado del hebreo קִרְיָה, empleado exclusivamente en la correspondencia aramea de Esdras 4:10-21. Todas las ocurrencias se refieren a Jerusalén en despachos oficiales a la corte persa, donde la ciudad se caracteriza como «rebelde y malvada» (Esd 4:12, 15). La forma enfática קִרְיְתָא y el constructo con preposiciones reflejan el estilo administrativo de la cancillería imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133395, 'spa', 'Una ciudad o villa amurallada, que funciona como sinónimo poético elevado de עִי', 'Una ciudad o villa amurallada, que funciona como sinónimo poético elevado de עִיר. Concentrado en textos proféticos y litúrgicos sobre Jerusalén: la ''ciudad fiel'' de Isaías convertida en ramera (Is 1:21, 26), la ''ciudad alegre'' silenciada por el juicio (Is 22:2), y la ''ciudad del gran Rey'' del salmista (Sal 48:2). También nombra la ciudad de Sijón en la poesía del desierto (Nm 21:28), ciudades en los resúmenes de conquista de Deuteronomio (Dt 2:36; 3:4), y la acusación de Oseas contra Galaad como ''ciudad de malhechores'' (Os 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133404, 'spa', 'Ciudad bíblica', 'Designa la ciudad moabita Queriot mencionada en Jeremías 48:24, 41 y Amós 2:2, así como un sitio en Judá en Josué 15:25. La Septuaginta la traduce como αἱ πόλεις (''las ciudades''), conservando el sentido plural. La Queriot moabita figura en la inscripción de Mesá (línea 13: קרית) y Eusebio la identifica con Rabat-Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133405, 'spa', 'Quiriat-Arba (topónimo)', 'Antiguo topónimo cananeo de Hebrón, que significa ''ciudad de cuatro'' o ''ciudad de Arba'' (un legendario ancestro de los anaquitas, Jos 14:15; 15:13; 21:11). En Génesis se vincula con los patriarcas: Sara muere allí (Gn 23:2) e Isaac reside en ese lugar (Gn 35:27). Los textos de Josué lo registran en las listas de conquista y ciudades levíticas (Jos 15:54; 20:7). Nehemías 11:25 atestigua su uso continuado en la época postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133412, 'spa', 'Quiriataim (topónimo)', 'Topónimo que significa ''ciudad doble'' (del dual de qiryah). Designa principalmente una ciudad moabita asignada a Rubén (Núm 32:37; Jos 13:19), mencionada en Génesis 14:5 y en oráculos contra Moab (Jer 48:1, 23; Ezeq 25:9), identificada con la actual Qureyat. Una segunda Quiriataim en Neftalí fue ciudad levítica (1 Cr 6:76).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133417, 'spa', 'Una ciudad gabaonita (Jos 9', 'Una ciudad gabaonita (Jos 9:17) cuyo nombre significa ''ciudad de los bosques,'' ubicada en la frontera entre Judá y Benjamín, famosa sobre todo como lugar de reposo del Arca del Pacto tras su retorno de Filistea (1 Sam 7:1-2; 1 Cr 13:5-6). También aparece en las listas de fronteras tribales (Jos 15:9, 60; 18:14-15), las genealogías de Judá (1 Cr 2:50-53), el censo del retorno postexílico (Neh 7:29; Esd 2:25), y como ciudad natal del profeta Urías hijo de Semaías (Jer 26:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133431, 'spa', 'nombre propio geográfico', 'Nombre propio de una antigua ciudad cananea, designación primitiva de Debir en el sur de Judá, que significa ''ciudad del libro'' o ''ciudad del escriba''. Las traducciones lo transliteran preservando su identidad como topónimo. Aparece en Josué 15:15-16 y Jueces 1:11-12, donde Otoniel la captura para ganar la mano de Acsa, hija de Caleb.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133433, 'spa', 'Resplandecer y cornear', 'En Éxodo 34:29-30, 35, el Qal describe el rostro de Moisés ''irradiando'' (קָרַן עוֹר פָּנָיו) tras hablar con Dios, un resplandor que aterró a los israelitas. En Salmo 69:31-32, el participio Hifil describe un buey ''con cuernos'' (מַקְרִן), es decir, plenamente desarrollado. Ambos sentidos comparten la raíz קֶרֶן, que puede denotar tanto cuerno como rayo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133434, 'spa', 'Cuerno (literal, físico)', 'Cuerno (literal, físico): un cuerno literal y físico, ya sea de carnero, buey o toro salvaje, y por extensión directa las proyecciones en forma de cuerno en las esquinas del altar, un cuerno usado como recipiente de aceite o un cuerno como trompeta. Es el sentido dominante con 67 apariciones: el carnero de Abraham atrapado por sus cuernos (Gn 22:13), los cuernos del altar untados con sangre (Éx 29:12; 30:2), el cuerno de aceite de unción (1 S 16:1; 1 R 1:39) y los cuernos en las visiones apocalípticas de Daniel (Dn 8:3-21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133441, 'spa', 'Cuerno como fuerza/poder', 'Cuerno como fuerza/poder: cuerno metafórico como fuerza, poderío, dignidad o poder político, el modismo del «cuerno exaltado». El cántico de Ana declara «mi cuerno es exaltado en el SEÑOR» (1 S 2:1); el salmista confía en que Dios «exaltará el cuerno de su ungido» (Sal 89:17, 24; 92:10). La transferencia metafórica del cuerno físico al poder abstracto es una de las figuras más persistentes de la Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133455, 'spa', 'Colina o ladera (topográfico)', 'Colina o ladera (topográfico): un accidente geográfico en forma de cuerno, una colina prominente, ladera fértil o promontorio. Is 5:1 sitúa la viña del amado en una «קֶרֶן de una colina fértil», donde la imagen es una ladera escalonada que sobresale como un cuerno. Esta única aparición preserva un antiguo mapeo metafórico de la anatomía animal al paisaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133457, 'spa', 'Rayos de luz', 'Rayos de luz: rayos o haces de luz que irradian de una teofanía divina, metafóricamente con forma de cuernos que se proyectan desde una fuente. Hab 3:4 describe el resplandor que emana de la mano de Dios, donde los «cuernos» se convierten en rayos de gloria. Los traductores de diversas tradiciones entendieron aquí קֶרֶן como luminosidad radiante, no como un apéndice animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133460, 'spa', 'Cuerno (instrumento musical)', 'Cuerno (instrumento musical). Cuerno como instrumento musical — específicamente el cuerno que suena en la orquesta real de Nabucodonosor, enumerado junto a la lira, el arpa, el trigón y las flautas (Dan 3:5, 7, 10, 15). Las cuatro apariciones describen la misma escena ceremonial: cuando el cuerno suena, todos los pueblos deben postrarse ante la imagen de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133461, 'spa', 'Cuerno (símbolo apocalíptico de poder)', 'Cuerno (símbolo apocalíptico de poder). Cuerno como símbolo apocalíptico de poder real o político en la visión de Daniel de las cuatro bestias (Dan 7:7-24). Los diez cuernos de la cuarta bestia se identifican explícitamente como diez reyes (7:24), y el ''cuerno pequeño'' que desarraiga a otros tres se convierte en una figura central de la interpretación escatológica. Todo el peso simbólico lo lleva el contexto visionario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133470, 'spa', 'Broche del tabernáculo', 'Broche o corchete metálico empleado para sujetar las cortinas del tabernáculo en una cubierta unificada. Los broches de oro (qarse zahav) unían las cortinas interiores de lino enganchando sus lazadas (Éx 26:6; 36:13), mientras que los broches de bronce (qarse nechoshet) conectaban las cortinas exteriores de pelo de cabra (Éx 26:11; 36:18). Figuran entre los componentes del tabernáculo tanto en las instrucciones como en el inventario final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133475, 'spa', 'Rasgar, desgarrar (vestiduras)', 'Rasgar, desgarrar (vestiduras): el sentido activo principal: rasgar o desgarrar, abrumadoramente vestiduras como expresión de duelo, luto, ira u horror religioso (47 de 63 apariciones). Es el gran gesto bíblico del lamento: Jacob rasga su vestidura ante la noticia de José (Gn 37:29, 34), Josué y Caleb rasgan las suyas ante la rebelión de Israel (Nm 14:6), David rasga la suya por la muerte de Saúl (2 S 1:11), y Josías rasga la suya al oír la Ley (2 R 22:11). Jl 2:13 ordena «rasgad vuestros corazones y no vuestras vestiduras», metáfora que solo funciona porque el acto físico era universal y comprendido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133477, 'spa', 'Rasgado (condición resultante)', 'Rasgado (condición resultante): participio pasivo del Qal que describe la condición resultante de estar rasgado (7 apariciones), usado atributiva o predicativamente de vestiduras ya en estado de rotura. El mensajero de la batalla llega ante Elí «con sus ropas rasgadas» (1 S 4:12); Husai se presenta ante David «con su manto rasgado» (2 S 15:32); los siervos de Ezequías acuden ante Isaías «con sus vestidos rasgados» (2 R 18:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133480, 'spa', 'Ser rasgado (pasivo Nifal)', 'Ser rasgado (pasivo Nifal): forma Nifal (pasiva/reflexiva): ser rasgado o llegar a rasgarse (5 apariciones), donde el sujeto recibe la acción en vez de realizarla. La vestidura sacerdotal «no se rasgará» (Éx 28:32; 39:23); el altar en Betel «fue rasgado» (1 R 13:3, 5); Saúl agarra el manto de Samuel «y se rasgó» (1 S 15:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133485, 'spa', 'Agrandar los ojos (figurado)', 'Agrandar los ojos (figurado): una única aparición en Jer 4:30 donde el verbo se usa en un sentido figurado inusual. El profeta se dirige a Jerusalén personificada: «aunque agrandes tus ojos con pintura», pero el hebreo literalmente dice «aunque rasgues tus ojos», usando קָרַע para el acto cosmético de ensanchar los ojos. La metáfora del desgarro se interpreta como embellecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133486, 'spa', 'Cortar, partir en dos', 'Cortar, partir en dos: un sentido distinto de cortar o partir un objeto físico (3 apariciones), donde la acción no es desgarrar vestiduras en duelo sino un corte deliberado. Joacim abre ventanas en su palacio (Jer 22:14); corta el rollo profético con un cuchillo de escriba y lo quema (Jer 36:23); Jeroboam arranca el reino de la casa de David (2 R 17:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133514, 'spa', 'Jirones de tela', 'Designa pedazos o fragmentos de tela rasgada. En 1 Reyes 11:30-31, Ahías rasga su manto nuevo en doce pedazos (שְׁנֵים עָשָׂר קְרָעִים), simbolizando la división del reino de Salomón. En 2 Reyes 2:12, Eliseo rasga sus propias ropas en señal de duelo. Proverbios 23:21 emplea ''harapos'' (קְרָעִים) como señal de la pobreza que sobreviene al borracho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133515, 'spa', 'pellizcar, guiñar, formar', 'Abarca la gama de gestos de pellizco y formación. El sentido de guiñar el ojo predomina (Prov 6:13; 10:10; Sal 35:19), describiendo señales astutas y maliciosas. El de apretar los labios (Prov 16:30) extiende el gesto a la boca. En Job 33:6 arrancar del barro conecta con la imaginería del Cercano Oriente antiguo sobre la creación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133518, 'spa', 'Piso, fondo', 'El piso o superficie inferior de una estructura. Usado para el piso del templo recubierto de oro (1 Re 6:15, 16, 30), el suelo del tabernáculo del cual se recoge polvo para la prueba de los celos (Núm 5:17), y extendido metafóricamente al ''fondo del mar'' (Am 9:3). Evoca una base horizontal sólida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133525, 'spa', 'Bastidor o tablón del Tabernáculo', 'Bastidor o tablón del Tabernáculo: bastidor o tablón vertical del Tabernáculo, el significado dominante en 50 apariciones. Se refiere a los elementos estructurales de madera de acacia revestidos de oro que formaban las paredes del santuario del desierto. Son piezas centrales en Éx 26:15-30 y 36:20-34, con bases de plata adicionales para cada tablón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133534, 'spa', 'Cubierta de un barco', 'Cubierta de un barco: entablado de la cubierta de un barco. Extensión metafórica única en Ez 27:6, donde Tiro es retratada como un magnífico navío cuya cubierta está construida con ciprés de las costas de Chipre. El sentido básico de «tabla labrada» se adapta a un contexto náutico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133535, 'spa', 'ciudad (poético)', 'Término poético y elevado para designar un asentamiento amurallado o comunidad urbana. Las cinco apariciones se sitúan en la poesía sapiencial (Job, Proverbios), lo cual sugiere un registro digno o arcaizante. En Proverbios 11:11 denota la ciudad como cuerpo político, no meramente como lugar físico. El francés emplea el más literario ''cité'', reflejando ese mismo matiz de registro elevado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133538, 'spa', 'Rastrojo, paja seca — Rastrojo, paja o tallos secos que quedan tras la cosecha, ', 'Rastrojo, paja seca — Rastrojo, paja o tallos secos que quedan tras la cosecha, usado abrumadoramente en lenguaje figurativo para lo insustancial, inflamable o fácilmente dispersable. La única ocurrencia literal describe a los esclavos israelitas recogiendo rastrojo para hacer ladrillos (Éx 5:12). Como metáfora de fuego expresa el juicio divino que consume a los malvados (Éx 15:7; Is 5:24; 47:14; Nah 1:10; Mal 3:19). Como metáfora de viento representa la dispersión de los impíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133547, 'spa', 'El sentido verbal principal en Hifil', 'El sentido verbal principal en Hifil: prestar atención, dar oído, escuchar con esmero. Abarca imperativos (''¡Atended!'' Is 28:23), perfectos narrativos (Jer 23:18) y oraciones pidiendo la atención divina (Sal 5:2; 66:19). En 1 Samuel 15:22, qashav aparece en paralelo con shama pero con el peso añadido de la obediencia receptiva: ''prestar atención es mejor que la grosura de carneros.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133551, 'spa', 'Uso participial o sustantivado', 'Uso participial o sustantivado: el que escucha atentamente, la persona atenta. En Proverbios, caracteriza al sabio frente al necio — el que presta atención a labios maliciosos (Pr 17:4), el gobernante que escucha mentiras (Pr 29:12) o el llamado frustrado de la Sabiduría porque nadie estaba maqshiv (Pr 1:24). Cantares 8:13 usa el participio plural con ternura: ''los compañeros escuchan.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133556, 'spa', 'Una única aparición en Qal en Isaías 32', 'Una única aparición en Qal en Isaías 32:3 donde los oídos ''atenderán'' — usando la raíz simple en lugar del Hifil causativo. Esta promesa profética de percepción restaurada (''los oídos de los que oyen, escucharán'') empareja qashav con shama, sugiriendo que en la era mesiánica la atención será algo natural, no impuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133580, 'spa', 'Atención receptiva', 'Capta la atención o respuesta receptiva como evidencia de vida o presencia. En 1 Reyes 18:29 no hay ''respuesta'' (קֶשֶׁב) de Baal pese a los frenéticos esfuerzos proféticos, demostrando la inactividad del ídolo. En 2 Reyes 4:31, Giezi informa que no hay ''señal de vida'' (קֶשֶׁב) del hijo de la sunamita. Isaías 21:7 emplea la construcción de acusativo cognado וְהִקְשִׁיב קֶשֶׁב רַב para intensificar la vigilancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133582, 'spa', 'oídos atentos', 'La palabra modifica ''oídos'' para solicitar atención enfocada y cuidadosa. En 2 Crónicas 6:40 y 7:15, Salomón pide a Dios que mantenga Sus ojos abiertos y Sus oídos atentos a las oraciones ofrecidas en el templo—enfatizando la escucha divina activa a los clamores de Su pueblo. Salmo 130:2 hace una súplica idéntica: ''Estén tus oídos atentos a la voz de mis súplicas.'' El término implica más que simplemente oír; requiere atención concentrada y receptividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133583, 'spa', 'Vasijas para libaciones', 'Identifica vasijas cúlticas, específicamente jarras o copas para libaciones. Éxodo 25:29 y 37:16 las enumeran entre los utensilios de la mesa; Números 4:7 especifica ''jarras de la libación'' (קְשׂוֹת הַנָּסֶךְ). 1 Crónicas 28:17 las incluye en las especificaciones de David para los utensilios del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133584, 'spa', 'El sentido dominante del Hifil causativo', 'El sentido dominante del Hifil causativo: obstinar, endurecer o poner rígido, casi siempre emparejado con ''cerviz'' (עֹרֶף) o ''corazón'' (לֵב). Es la palabra para la rebelión espiritual deliberada — Faraón endureciendo su corazón (Éx 7:3; 13:15), Israel endureciendo su cerviz (Dt 10:16; 2 Cr 30:8), y Roboam negándose a aliviar el yugo de su padre (1 Re 12:4). Con 19 apariciones domina abrumadoramente el perfil del lema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133586, 'spa', 'El Qal estativo', 'El Qal estativo: ser duro, áspero, severo o feroz en carácter o acción. Génesis 49:7 condena la ira ''cruel'' de Simeón y Leví; 1 Samuel 5:7 registra que la mano de Yahvé ''fue severa'' sobre los filisteos; 2 Samuel 19:43 describe las palabras de los hombres de Judá como ''más duras'' que las de Israel. El español cruel y el francés cruel aparecen aquí, marcando la dimensión de juicio cualitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133590, 'spa', 'Un sentido obstétrico especializado', 'Un sentido obstétrico especializado: tener un parto difícil, experimentar dificultad en el alumbramiento. Ambas apariciones describen el parto fatal de Raquel al dar a luz a Benjamín (Gn 35:16-17), y el infinitivo constructo Piel/Hifil marca la intensidad de la prueba física. El español dificultad y el alemán schwer seleccionan vocabulario de dificultad médica en lugar de términos de dureza moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133591, 'spa', 'El sentido Qal de ser difícil, arduo de lograr o resolver', 'El sentido Qal de ser difícil, arduo de lograr o resolver. Deuteronomio 1:17 advierte a los jueces que no retrocedan ante un caso que ''sea demasiado difícil,'' y Deuteronomio 15:18 asegura al amo que liberar a un esclavo ''no le parezca duro'' a sus ojos. El español difícil y el alemán hart seleccionan vocabulario de dificultad de tarea en vez de severidad de carácter.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133602, 'spa', 'El Nifal pasivo', 'El Nifal pasivo: estar duramente oprimido, en angustia severa. Una sola aparición (Is 8:21) describe al caminante famélico que, ''duramente oprimido y hambriento,'' maldice a su rey y a su Dios. La voz pasiva marca al sujeto como víctima y no como agente de la dureza — una distinción semántica clave frente a los sentidos 1-2 donde el sujeto causa o encarna la dureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133606, 'spa', 'El Hifil en una aplicación no relacionada con la obstinación', 'El Hifil en una aplicación no relacionada con la obstinación: hacer algo difícil, pedir algo arduo. Elías le dice a Eliseo, ''Has pedido cosa difícil'' (2 Re 2:10) — la doble porción de espíritu. El español cosa difícil y el alemán schwer seleccionan vocabulario de dificultad en lugar de vocabulario de terquedad, confirmando este como el sentido secundario del Hifil: hacer una tarea difícil en vez de endurecer una voluntad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133608, 'spa', 'Trato áspero o severo hacia otros — conducta ruda, cruel u opresiva', 'Trato áspero o severo hacia otros — conducta ruda, cruel u opresiva. José habla ''duramente'' a sus hermanos (Gn 42:7, 30), y Nabal es descrito como ''duro'' en su trato (1 S 25:3). Las glosas multilingües emparejan consistentemente este sentido con palabras de crueldad y severidad, reflejando la dureza más concreta e inflexible aplicada a la interacción humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133609, 'spa', 'Duro de cerviz, obstinado — negativa terca a ceder, especialmente hacia Dios', 'Duro de cerviz, obstinado — negativa terca a ceder, especialmente hacia Dios. Aparece casi siempre en la frase constructa ''duro de cerviz'' (Éx 32:9; 33:3, 5; 34:9; Dt 9:6) o ''duro de rostro/corazón'' (Ez 2:4; 3:7). Este sentido domina las narraciones pentateucas de la rebelión de Israel en el desierto, evocando la vívida metáfora corporal de un animal que se niega a girar el cuello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133610, 'spa', 'Duro o difícil referido a circunstancias — tareas pesadas, condiciones penosas o', 'Duro o difícil referido a circunstancias — tareas pesadas, condiciones penosas o situaciones vitales dolorosas. Describe la ''dura servidumbre'' de la esclavitud egipcia (Éx 1:14; 6:9), un caso legal demasiado ''difícil'' para los jueces ordinarios (Éx 18:26) y la angustia aplastante del cautiverio (Dt 26:6). En 1 Samuel 1:15, Ana se llama a sí misma ''dura de espíritu'' — alguien cuya vida es amarga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133611, 'spa', 'Feroz, intenso referido a fuerza o ira — describiendo poder abrumador en batalla', 'Feroz, intenso referido a fuerza o ira — describiendo poder abrumador en batalla, viento o ira divina. Jueces 4:24 retrata la mano de Israel haciéndose ''cada vez más dura'' contra Jabín; Isaías 27:1 habla de la ''espada dura y grande'' de Dios; Isaías 27:8 menciona un ''viento recio del oriente.'' Este sentido se desplaza de la dureza hacia la potencia bruta, captando fuerzas que no pueden ser resistidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133635, 'spa', 'unidad monetaria antigua', 'Este término raro designa una unidad monetaria o de peso antigua conocida en tiempos patriarcales pero oscura en períodos posteriores. Génesis 33:19 y Josué 24:32 registran la compra de Jacob del terreno de Siquem por ''cien quesitás,'' estableciendo el campo de sepultura familiar. Job 42:11 lo usa para los regalos de restauración dados por amigos y parientes—''cada uno le dio una quesitá y un anillo de oro.'' El emparejamiento con oro sugiere valor sustancial, pero la cantidad exacta sigue siendo incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133636, 'spa', 'Escama', 'La escama de pez, reptil o cocodrilo, y por extensión la armadura escamada. Central en las leyes dietéticas: criaturas acuáticas con aletas y escamas son limpias (Lev 11:9-12; Deut 14:9-10). En 1 Samuel 17:5 describe la cota de escamas de Goliat (שִׁרְיוֹן קַשְׂקַשִּׂים), y Ezequiel 29:4 lo aplica al Faraón como cocodrilo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133639, 'spa', 'El sentido político-conspirativo', 'El sentido político-conspirativo: conspirar, tramar o formar una rebelión contra un gobernante, con 21 apariciones concentradas en la Historia Deuteronomista. La fórmula wayyiqshor X ''al Y (''y X conspiró contra Y'') se repite como estribillo narrativo a lo largo de los golpes sucesivos del reino del norte (1 R 15:27; 16:9, 16, 20; 2 R 9:14; 10:9; 12:20; 15:10, 25, 30; 21:23-24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133641, 'spa', 'El sentido físico concreto', 'El sentido físico concreto: atar, amarrar o sujetar algo con una cuerda, con 13 apariciones en la literatura patriarcal, legal y sapiencial. La nuera de Judá ata un hilo escarlata en la mano del primogénito (Gn 38:28); Israel recibe el mandato de atar las palabras de la Torá ''como señal en tu mano'' (Dt 6:8; 11:18); Proverbios exhorta a atar la misericordia y la verdad al cuello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133646, 'spa', 'El sentido pasivo-estativo', 'El sentido pasivo-estativo: estar atado, ligado o profundamente vinculado, expresado mediante participios pasivos del Qal y formas Nifal en 3 apariciones. El alma de Jacob ''estaba ligada (qeshurah) al alma del muchacho'' (Gn 44:30), imagen conmovedora del amor paternal como nudo irrompible. El alma de Jonatán ''se ligó (niqsherah) al alma de David'' (1 S 18:1). Proverbios 22:15 advierte que ''la necedad está atada al corazón del muchacho''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133647, 'spa', 'El participio activo sustantivado', 'El participio activo sustantivado: conspiradores, los que conspiran, funcionando como sustantivo en 4 apariciones. Cuando la rebelión de Absalón cobra fuerza, se le informa a David que ''Ahitofel está entre los conspiradores (haqqosherim) con Absalón'' (2 S 15:31). Tras el asesinato de Amón, ''el pueblo de la tierra mató a todos los conspiradores'' (2 R 21:24; 2 Cr 33:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133655, 'spa', 'Una única aparición en Nehemías 4', 'Una única aparición en Nehemías 4:6 [hebreo 3:38] donde el muro ''fue unido'' (wattiqasher) hasta la mitad de su altura, describiendo la conexión estructural de las secciones del muro que se enlazan formando un todo continuo. Este uso extiende el sentido de atadura física (sentido 2) al ámbito de la construcción arquitectónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133657, 'spa', 'El sentido del participio Pual que describe al ganado como fuerte o robusto, un ', 'El sentido del participio Pual que describe al ganado como fuerte o robusto, un uso agrícola único limitado a 2 apariciones en Génesis 30:41-42. Jacob colocó las varas frente a las ovejas ''robustas'' (meqUshsharoth) durante el apareamiento, separándolas de las más débiles. Esto puede reflejar un sentido subyacente de ''firmemente constituido, compacto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133668, 'spa', 'Conspiración — Conspiración o complot traicionero contra un gobernante o autorid', 'Conspiración — Conspiración o complot traicionero contra un gobernante o autoridad establecida, el sentido exclusivo de קֶשֶׁר en todas sus dieciséis ocurrencias. Funciona como término político-histórico en las narrativas de regicidio de Reyes (1 Re 16:20; 2 Re 12:21; 14:19; 15:15, 30; 17:4), siendo su uso más dramático el grito de pánico de Atalía ''¡Conspiración!'' en la coronación de Joás (2 Re 11:14). Los textos proféticos lo extienden a complots contra el pueblo de Dios (Jer 11:9; Ez 22:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133674, 'spa', 'Recoger, juntar leña', 'Recoger palos, rastrojo o leña — forrajear en busca de combustibles, frecuentemente bajo coacción o pobreza. Los esclavos israelitas recogen rastrojo para ladrillos bajo Faraón (Éx 5:7, 12), haciendo de este verbo expresión de trabajo forzado. Un hombre recoge leña en sábado como caso jurídico (Núm 15:32-33), y la viuda de Sarepta recoge sus últimos palos (1 Re 17:10, 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133679, 'spa', 'Arco (arma)', 'Arco (arma): el arco como arma usada para disparar flechas en batalla o cacería. Es el sentido dominante en 72 apariciones. Representa el poderío militar: el arco de José permaneció firme (Gn 49:24), el arco de Jonatán nunca retrocedió (2 S 1:22), y Dios quiebra el arco para poner fin a la guerra (Sal 46:9). El «Cántico del Arco» (2 S 1:18) y la destreza de los arqueros benjaminitas (1 Cr 12:2) confirman su centralidad bélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133683, 'spa', 'Arco iris (arco en el cielo)', 'Arco iris (arco en el cielo): el arco iris, el arco de Dios colocado en las nubes como señal del pacto después del Diluvio. Aparece en Gn 9:13-16 y Ez 1:28. El posesivo «mi arco» (Gn 9:13) presenta el arco iris como el arma propia de Dios, ahora colgada en el cielo en señal de paz, transformando un instrumento de guerra en garantía de misericordia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133710, 'spa', 'Qal: ver, percibir', 'El amplio núcleo del verbo en todas las formas Qal: ver, observar, percibir, experimentar. Las traducciones multilingües emplean consistentemente verbos básicos de visión — español vio, francés vit, alemán sah, coreano 보다, suajili kuona. Abarca desde ''Dios vio la luz'' (Gn 1:4) hasta ''he visto la aflicción'' (Lm 3:1), incluyendo el ver metafórico como comprender.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133769, 'spa', 'Nifal: aparecer, ser visto', 'Nifal (pasivo/reflexivo): aparecer o ser visto. Predomina el lenguaje teofánico — ''YHWH se apareció a Abram'' (Gn 12:7), ''se apareció a Isaac'' (Gn 26:2). El español aparecer, el francés apparaître y el suajili kuonekana distinguen este sentido del ver activo, reflejando el giro hacia la autorrevelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133771, 'spa', 'participio Qal: vidente', 'El participio activo Qal usado sustantivamente como título: רֹאֶה, ''vidente''. 1 Samuel 9:9 glosa explícitamente el término: ''al que hoy se llama profeta, antiguamente se le llamaba vidente''. El árabe ra''iy, el coreano 보는 자 y el suajili mwonaji conservan el origen participial que vincula la visión con el oficio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133794, 'spa', 'Qal: proveer, prever', 'Un sentido Qal especializado: encargarse de un asunto, proveer. Paradigmáticamente en Gn 22:8, ''Dios proveerá (yir''eh) para sí el cordero'', que da origen al topónimo YHWH-Yiré (Gn 22:14). El español proveerá capta este matiz providencial donde el ver se desliza hacia la provisión y el cuidado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133837, 'spa', 'Hifil: mostrar', 'Hifil (causativo): mostrar o hacer ver a alguien algo. Dios muestra a Moisés la tierra (Dt 34:1), Moisés pide ''muéstrame tu gloria'' (Éx 33:18). El árabe أَرَى (Forma IV), el coreano 보여주다 y el suajili kuonyesha recurren a morfología causativa dedicada, confirmando la distinción a nivel de tema verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133870, 'spa', 'Hofal: ser mostrado', 'Hofal (pasivo causativo): ser mostrado o hecho ver. En Éx 26:30 se ordena a Moisés erigir el tabernáculo ''conforme al modelo que te fue mostrado en el monte''. El español te fue mostrado y la morfología del Hofal marcan la doble pasivización: ser hecho ver por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133912, 'spa', 'vidente profético', 'Título profético arcaico que designa a quien recibe revelación divina mediante visión. El narrador de 1 Samuel lo señala explícitamente como la palabra antigua reemplazada por נָבִיא (''profeta''). Las cinco apariciones pertenecen al relato de Samuel (1 S 9:9, 11, 18, 19). El español ''vidente'' conserva con precisión la raíz visual del hebreo רֹאֶה, vinculando la percepción sobrenatural con el oficio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133915, 'spa', 'El nombre propio Rubén, que designa (a) al hijo primogénito de Jacob con Lea, cu', 'El nombre propio Rubén, que designa (a) al hijo primogénito de Jacob con Lea, cuyo nombre contiene un juego de palabras con ''¡he aquí, un hijo!'' y ''Dios ha visto mi aflicción'' (Gn 29:32; 35:22; 49:3-4), (b) la tribu israelita descendiente de él y su territorio transjordano al este del Mar Muerto (Nm 32; Jos 13:15-23; Dt 33:6), y (c) la porción tribal en la visión escatológica de Ezequiel (Ez 48:6-7). A pesar de perder la primogenitura por haber profanado el lecho de su padre, el nombre permanece prominente en listas tribales, genealogías y la distribución de la tierra prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133921, 'spa', 'Rubenita (gentilicio) — Gentilicio que designa a los miembros de la tribu de Rub', 'Rubenita (gentilicio) — Gentilicio que designa a los miembros de la tribu de Rubén, usado tanto para individuos (1 Cr 11:42) como colectivamente con el artículo para todo el clan. Los rubenitas se asentaron al este del Jordán (Dt 3:12; Jos 13:8), mencionados frecuentemente junto a los gaditas y la media tribu de Manasés. Su territorio estuvo expuesto a incursiones extranjeras: las campañas de Hazael (2 Re 10:33) y el eventual exilio asirio bajo Tiglat-piléser III (1 Cr 5:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133936, 'spa', 'visión, apariencia, espectáculo', 'Abarca tres campos semánticos: la visión activa (percepción divina), la apariencia (aspecto físico) y el espectáculo (exhibición pública). Génesis 16:13 ancla el sentido activo: Dios como el que ve. ''Roi'' conserva el nombre hebreo directamente, mientras ''apariencia'' y ''espectáculo'' captan los sentidos pasivos. La progresión va desde la visión de Dios (Gn 16:13) hasta ser visto en la enfermedad (Job 33:21) y ser convertido en espectáculo público (Nah 3:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133937, 'spa', 'Nombre personal tripartito', 'Nombre propio de tres individuos: (1) un judahita en 1 Crónicas 4:2, posiblemente idéntico a Haroé en 2:52; (2) un rubenita en 1 Crónicas 5:5; (3) un jefe de familia de los sirvientes del templo en Esdras 2:47 y Nehemías 7:50. El elemento teofórico יָה unido a רָאָה (''ver'') produce el significado ''Yahveh ha visto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133940, 'spa', 'Toro salvaje, uro', 'El toro salvaje o uro (Bos primigenius), un bóvido grande, feroz e indomable, hoy extinto, empleado como símbolo de fuerza arrolladora. El poder de Dios se compara con sus cuernos (Nm 23:22; 24:8), la fuerza tribal de José se asemeja a su embestida (Dt 33:17), y Job 39:9-10 usa su carácter indómito para ilustrar criaturas que escapan al control humano. Los Salmos 22:22 y 29:6 lo emplean en imágenes de peligro y poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133946, 'spa', 'Ramot de Galaad', 'Designa a Ramot en Galaad, ciudad levítica de refugio asignada a Gad en Deuteronomio 4:43, Josué 20:8 y 1 Crónicas 6:73, 80. Corresponde a רָמֹת גִּלְעָד, mencionada 19 veces en Reyes y Crónicas, donde Acab murió en batalla (1 Reyes 22) y Jehú fue ungido (2 Reyes 9). La forma plural denota ''alturas'', acorde al terreno elevado de Galaad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133947, 'spa', 'Cabeza (parte del cuerpo)', 'Cabeza (parte del cuerpo). La cabeza física de una persona, animal o figura visionaria. Predomina en las narrativas de la corte y las visiones apocalípticas de Daniel (Dan 2:32, 38; 3:27; 7:6, 9, 20), con la frase ''visiones de tu cabeza'' (Dan 2:28; 4:5, 10; 7:1, 15) usando ''cabeza'' como la sede corporal de los sueños.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133949, 'spa', 'Jefe, líder', 'Jefe, líder. Extensión metafórica de ''cabeza'' para denotar autoridad. Usado en Esdras 5:10 donde se toman nombres ''a la cabeza de ellos'', es decir, de sus líderes. Diversas traducciones confirman independientemente el significado de rango social en lugar de una lectura de parte del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133956, 'spa', 'Resumen, punto principal', 'Resumen, punto principal. La suma, el punto principal o el contenido esencial de un asunto. En Daniel 7:1, el profeta escribe ''el resumen de los asuntos'', un sentido abstracto donde ''cabeza'' se convierte en ''esencia''. El español ''resumen'' apunta directamente a este significado sintetizador y destilado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133957, 'spa', 'cabeza (variante)', 'La cabeza física y literal de un ser humano o animal, idéntica al sentido 1 en contenido semántico. Representa un subconjunto separado por distribución estadística en los datos de traducción, pero designa la misma parte anatómica y sus contextos habituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133958, 'spa', 'jefe, líder de grupo', 'Un jefe, líder o cabeza de un clan, tribu o unidad administrativa. La metáfora de parte del cuerpo a figura de autoridad es pansemítica (árabe ra''is, suajili mkuu). Prominente en los registros genealógicos de Crónicas (1 Cr 5:7, 5:24), donde los líderes tribales se enumeran por su jefatura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133962, 'spa', 'cima, cumbre, cúspide', 'La cima, cumbre o pico de un objeto físico: una montaña, columna, árbol o torre. Moisés de pie en la cima del collado con la vara de Dios (Éx 17:9-10) y la nube cubriendo la cumbre del Sinaí (Éx 19:20) son pasajes definitorios de este sentido espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133977, 'spa', 'principio, primero', 'El comienzo o primero de una secuencia temporal u ordinal. La cabeza del tiempo es su inicio: Proverbios 8:23 sitúa a la Sabiduría al principio de las obras de Dios, y Números 10:10 prescribe toques de trompeta al principio de los meses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133996, 'spa', 'compañía, división militar', 'Una compañía, división o banda de asalto militar, generalmente en plural. Jueces 7:16 describe a Gedeón dividiendo a trescientos hombres en tres compañías, y Jueces 9:34-43 narra el despliegue táctico de Abimelec en múltiples bandas. Un sentido militar especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134030, 'spa', 'lo más selecto, capital', 'Lo más selecto, excelente o principal de una sustancia, o el monto capital de una deuda. En Lv 6:5 y Nm 5:7 el vocablo se refiere al capital principal que debe restituirse más una quinta parte. La metáfora cualitativa va de ''cabeza'' a ''lo primordial o mejor.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134037, 'spa', 'suma, total censal', 'La suma o total obtenido al contar cabezas, una cifra censal. El modismo naso et rosh (''levantar la cabeza'') significa ''hacer un censo.'' El Salmo 139:17 usa el vocablo para la suma de los pensamientos de Dios, y el Salmo 119:160 habla de la suma de la palabra de Dios como verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134082, 'spa', 'pueblo o título', 'El término aparece tres veces en Ezequiel 38-39 en el título ''Gog, príncipe de Ros, Mesec y Tubal.'' Si es nombre propio, Ros designa a un grupo étnico norteño desconocido aliado con Mesec (Mushki/Frigios) y Tubal. Si se lee como el sustantivo común ''cabeza,'' significaría ''príncipe principal'' en vez de nombrar a una nación distinta. La transliteración de la Septuaginta como nombre (Ρως) apoya la interpretación étnica, mientras la similitud con la palabra hebrea común invita a la ambigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134083, 'spa', 'Veneno, ponzona, hiel', 'Veneno, ponzona o hiel: sustancia toxica o amarga usada figuradamente para expresar juicio divino, justicia corrompida o sufrimiento intenso. Deuteronomio 32:33 habla del ''veneno de serpientes'', Salmo 69:21 de recibir ''veneno'' como alimento, y Amos 6:12 de la justicia convertida ''en veneno''. Su frecuente combinacion con ajenjo (Dt 29:18; Lm 3:19; Jer 9:15; 23:15) establece una imagen recurrente de amargura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134085, 'spa', 'Cabeza (confusion de homonimos)', 'Aparente confusion con el homonimo rosh I (''cabeza, jefe'') en Job 20:16. Las traducciones al ingles, al arabe y al coreano interpretan el termino como ''cabeza'' en lugar de ''veneno'', aunque el contexto --chupar el veneno de cobras-- favorece claramente el sentido toxico. Este grupo probablemente refleja una dificultad de desambiguacion mas que un significado genuinamente distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134088, 'spa', 'Planta venenosa', 'Planta venenosa o hierba toxica como entidad botanica, enfocandose en la planta que crece y no en la sustancia extraida. Oseas 10:4 describe el juicio brotando ''como hierba venenosa en los surcos del campo''. La imagen es de vegetacion toxica que crece silvestre donde deberia florecer la justicia, una vivida metafora agraria de la corrupcion moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134094, 'spa', 'primero (ordinal)', 'Ordinal directo ''primero'' en una secuencia: primer mes, primer día, primer hijo. Este es el uso dominante (107 de 182 apariciones), anclando listas calendáricas y genealógicas a lo largo del Pentateuco y los libros históricos (Gn 25:25; Éx 12:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134097, 'spa', 'anterior, previo', 'Adjetivo que significa ''anterior'' o ''previo,'' contrastando un estado pasado con uno presente o posterior. Oseas 2:9 lo usa para el ''primer marido'' de la esposa, y Hageo 2:3 para la ''gloria primera'' del templo. El matiz temporal-comparativo queda bien captado por el español anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134101, 'spa', 'al principio, antes', 'Uso adverbial con preposiciones (ba-rishonah, ka-rishonah) con el sentido de ''al principio,'' ''en el comienzo'' o ''en tiempos pasados.'' Génesis 13:4 señala el lugar donde Abram había construido ''al principio'' un altar. Es un uso preposicional fosilizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134104, 'spa', 'cosas anteriores (profético)', 'Sustantivo femenino plural ha-rishonot, ''las cosas primeras'' o anteriores: eventos, profecías u obras divinas previas, concentradas en los discursos de juicio de Isaías (Is 41:22; 42:9; 43:9, 18; 46:9). La capacidad de Dios de declarar ''las cosas primeras'' que se cumplieron valida la nueva profecía. Un uso teológicamente distintivo de Isaías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134105, 'spa', 'como al principio', 'La construcción comparativa ka-rishon/ka-rishonah — ''como al principio,'' ''como el primero'' — que expresa restauración o retorno a una condición original. Las segundas tablas de Moisés ''como las primeras'' (Éx 34:1) y la promesa profética de jueces ''como al principio'' (Is 1:26) portan matices de restauración pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134116, 'spa', 'antepasados, los primeros', 'Sustantivo masculino plural ha-rishonim, ''los primeros,'' referido a antepasados o predecesores. Levítico 26:45 invoca el pacto de ''los primeros'' sacados de Egipto. Deuteronomio 4:32 dirige la indagación hacia ''los días primeros.'' El uso personaliza la historia como memoria viva de un pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134130, 'spa', 'principal, preeminente', 'Una aparición aislada en 1 Crónicas 18:17 donde el plural parece significar ''principales'' o ''destacados,'' describiendo a los hijos de David. El sentido refleja una extensión de ''primero en secuencia'' a ''primero en importancia,'' paralelo al árabe awwal que también puede significar ''preeminente.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134134, 'spa', 'desde el principio', 'Un uso singular en Jeremías 17:12 en la frase me-rishon, ''desde el principio,'' describiendo el trono de gloria como exaltado ''desde lo primero.'' Este sentido temporal absoluto apunta a un origen primordial, aproximándose al significado del hebreo qedem.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134136, 'spa', 'El sentido temporal de principio o comienzo, anclado por la icónica apertura de ', 'El sentido temporal de principio o comienzo, anclado por la icónica apertura de las Escrituras: ''En el principio'' (Gn 1:1). Marca el inicio de reinos (Gn 10:10), reinados (Jer 26:1; 28:1) y años (Dt 11:12). Eclesiastés 7:8 contrasta ''el principio de un asunto'' con su final, y Proverbios 1:7 declara que ''el temor de Jehová es el principio de la sabiduría.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134137, 'spa', 'El sentido cúltico-agrícola de primicias', 'El sentido cúltico-agrícola de primicias: el primer fruto del campo, del rebaño o de la masa, consagrado como ofrenda a Dios. Abarca 25 apariciones y figura prominentemente en las leyes de ofrendas: las primicias de la siega de trigo (Éx 23:19; 34:26), de la harina gruesa (Nm 15:20-21) y del grano y el vino (Dt 18:4). El español ''primicias'' conserva bien el matiz sacro-agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134153, 'spa', 'Un sentido cualitativo que indica lo principal, lo mejor o lo más escogido, enfa', 'Un sentido cualitativo que indica lo principal, lo mejor o lo más escogido, enfatizando rango o calidad en lugar de prioridad temporal. En Deuteronomio 33:21, la porción del líder se denomina ''la primera parte'' (es decir, la más selecta). Amós 6:1 y 6:6 lo emplean para ''la primera de las naciones'' y ''los aceites más finos.'' 1 Samuel 15:21 se refiere a ''lo principal de las cosas consagradas al anatema.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134169, 'spa', 'muchos, mucho (cuantitativo)', 'El sentido más frecuente (305 veces): pluralidad cuantitativa directa: ''muchas'' personas, animales o cosas; ''mucho'' plata, grano o años. Los datos interlingüísticos convergen fuertemente aquí — árabe كَثِير, coreano 많은, suajili -engi, hindi बहुत — demostrando que este es el núcleo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134171, 'spa', 'grande, poderoso (cualitativo)', 'El salto cualitativo a ''grande, poderoso'' (65 veces) describe intensidad o importancia: ''gran maldad'' (Gn 6:5), ''gran abismo'' (Gn 7:11), ''lluvia copiosa'' (1 Sam 12:17). Los paralelos multilingües — árabe عَظِيم, coreano 큰, hindi बड़ा — muestran la grandeza cualitativa como extensión semántica natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134175, 'spa', 'grandemente, largo (adverbial)', 'Uso adverbial (8 veces) que indica grado (''grandemente'') o extensión (''largo, lejos''): ''grandemente multiplicado'' (Sal 65:9), ''largo tiempo he morado'' (Sal 120:6). Propio de la poesía o la prosa elevada (1 Re 19:7; Sal 62:2; 123:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134180, 'spa', 'basta, suficiente', 'Como exclamación o predicado (14 veces), expresa suficiencia: ''¡Basta! Ya he visto bastante'' (Gn 45:28), ''¡Basta ya! ¡Dejad de contender!'' (Nm 16:3, 7). La extensión pragmática va del cuantitativo ''mucho'' al evaluativo ''suficiente.'' Frecuente en contextos imperativos u hortativos (Dt 1:6; Éx 9:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134181, 'spa', 'abundante en, rico en', 'En estado constructo (19 veces) el adjetivo significa ''abundante en, rico en'' al modificar otro sustantivo: ''abundante en misericordia'' (Éx 34:6; Nm 14:18), ''grande en obras'' (2 Sam 23:20). Este uso atributivo-constructo resalta la cualidad de poseer algo en abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134187, 'spa', 'más, mayor (comparativo)', 'Sentido comparativo ''más, mayor'' (10 veces), que aparece al contrastar con otra entidad: ''el mayor servirá al menor'' (Gn 25:23), ''un pueblo más numeroso y poderoso'' (Dt 20:1). Se emplea en contextos donde se comparan explícitamente dos cantidades o magnitudes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134220, 'spa', 'abundancia, multitud (nominal)', 'Sentido nominal o sustantivado (5 veces) que significa ''abundancia, multitud, grandeza'' al usarse con preposiciones o en estado constructo: ''por la grandeza de su poder'' (Job 36:18), ''con mucho dolor'' (Ecl 1:18). Concentrado en la literatura sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134222, 'spa', 'aumentar, multiplicarse (verbal)', 'Formas verbales del Qal (4 veces) que significan ''llegar a ser muchos, aumentar, multiplicarse'' — raras pero atestiguadas. Se encuentran en Éx 23:29 (''para que no se multipliquen las fieras''), 1 Sam 14:19 (''el tumulto iba creciendo''), 2 Sam 15:12 (''la conspiración se fortalecía'') e Is 6:12 (''la desolación sea grande'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134226, 'spa', 'jefe, capitán (título)', 'Título sustantivado רַב que significa ''jefe, capitán, señor'' (2 veces), en Pr 26:10 (posiblemente ''un grande'' o ''un arquero'' — texto incierto) y Jer 52:24 (''capitán de la guardia''). Compárese con el acadio rabû y el posterior arameo rab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134250, 'spa', 'grande (incierto)', 'Una aparición incierta en Is 19:20 donde el contexto es difícil y las traducciones divergen — posiblemente ''defensor'' o ''uno grande.'' Los datos multilingües muestran variación, lo que sugiere oscuridad textual o contextual. Podría pertenecer al sentido 2 (grande cualitativo) o al 9 (título), pero resulta ambiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134270, 'spa', 'Título que significa ''jefe'' o ''capitán,'' tomado del vocabulario administrativo a', 'Título que significa ''jefe'' o ''capitán,'' tomado del vocabulario administrativo acadio, usado exclusivamente en designaciones compuestas para funcionarios de la corte babilónica y asiria. Se refiere abrumadoramente a rav-tabbachim, el ''jefe de la guardia'' Nebuzaradán, en los relatos de la caída de Jerusalén (2 R 25:8-20; Jer 39:9-13; 52:12-30). También designa al rav-saris sobre la formación de Daniel (Dan 1:3), al capitán del barco en la narrativa de Jonás (Jon 1:6) y a los jefes de cada casa en Est 1:8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134277, 'spa', 'Grande, enorme (cualidad adjetival)', 'Grande, enorme (cualidad adjetival). Describe magnitud, tamaño o importancia como adjetivo cualitativo: la gran imagen (Dan 2:31), las grandes bestias (Dan 7:3, 7), un gran banquete (Dan 5:1) y grandes señales (Dan 3:33). También se usa comparativamente con min (''mayor que'', Dan 7:20). Abarca tanto la escala física como la importancia abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134278, 'spa', 'Jefe, funcionario principal (titular)', 'Jefe, funcionario principal (titular). Funciona como título sustantivado en cadenas constructas que designan rango oficial: ''jefe de los verdugos'' (rav tabbajayya, Dan 2:14), ''jefe de los prefectos'' (rav siginin, Dan 2:48) y ''jefe de los magos'' (rav jartummayya, Dan 4:6; 5:11). Este uso titular se distingue claramente del sentido puramente adjetival, reflejando un patrón bien atestiguado en el arameo de corte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134284, 'spa', 'abundancia, multitud', 'El sentido nominal nuclear: una gran cantidad, número o monto de algo — ''multitud'' o ''abundancia.'' Es el uso dominante con 132 apariciones. Aparece en cadenas constructas (רֹב + genitivo) en todos los ámbitos: multitud de pueblo (Pr 14:28), abundancia de sacrificios (Is 1:11), cantidad de posesiones (Gn 27:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134299, 'spa', 'grandeza, magnitud', 'El sentido cualitativo: grandeza, magnitud o extensión impresionante, no el simple recuento sino la escala sobrecogedora de algo. Se distingue del sentido 1 por la evidencia interlingüística: español grandeza (no abundancia), hindi बड़ाई (''inmensidad''). Las 10 apariciones se centran en los atributos de Dios y sus actos poderosos (Éx 15:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134305, 'spa', 'muchos, mucho (cuantificador)', 'Uso adjetival o adverbial como cuantificador que significa ''muchos,'' ''mucho'' o ''la mayoría,'' funcionando como modificador más que como sustantivo abstracto. Cinco apariciones donde el vocablo modifica en vez de estar solo. Pasaje clave: Ester 10:3 (''grande entre los judíos y aceptado por la multitud de sus hermanos'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134313, 'spa', 'ser abundante (Qal verbal)', 'Uso verbal raro de la raíz ר-ב-ב en Qal: ''ser abundante, ser numeroso.'' Solo 2 apariciones conservan este carácter verbal. Deuteronomio 7:7 es crucial: ''No porque fueseis más numerosos que todos los pueblos Yahvé os amó, pues erais el más pequeño de todos.'' El sentido verbal subyace a la forma nominal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134345, 'spa', 'Ser o llegar a ser muchos, numerosos; multiplicarse o aumentar', 'Ser o llegar a ser muchos, numerosos; multiplicarse o aumentar. Sentido estativo/intransitivo del Qal que describe el crecimiento en numero de personas, problemas, pecados u otras entidades contables. Con 12 ocurrencias, este sentido abarca desde la narrativa primordial (''los hombres comenzaron a multiplicarse sobre la faz de la tierra,'' Gen 6:1) hasta salmos de angustia (''cuantos son los que se levantan contra mi,'' Sal 3:1; ''mis iniquidades se han multiplicado'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134349, 'spa', 'Ser producido o multiplicado por decenas de miles', 'Ser producido o multiplicado por decenas de miles. Participio Pual (pasivo intensivo) que describe un rendimiento agricola prodigioso en Salmo 144:13: rebanos merubbavot (''produciendo por decenas de miles'') en los campos. Esta unica ocurrencia preserva una conexion vivida entre el verbo ravav y el sustantivo revavah (''miriada, diez mil''), pintando un cuadro de abundancia pastoral tan grande que solo puede expresarse en terminos de miriadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134356, 'spa', 'Miríadas (multitud innumerable) — Multitud innumerable o hueste incontable, usad', 'Miríadas (multitud innumerable) — Multitud innumerable o hueste incontable, usado en la forma constructa plural para transmitir números abrumadoramente grandes que resisten el conteo exacto. Rebeca es bendecida para ser ''millares de miríadas'' (Gn 24:60), Moisés invoca a Dios llegando ''desde miríadas de santos'' (Dt 33:2), y el Cantar de los Cantares describe al amado como ''distinguido entre diez mil'' en sentido hiperbólico (Cnt 5:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134357, 'spa', 'Diez mil (número específico) — El numeral específico diez mil, funcionando como ', 'Diez mil (número específico) — El numeral específico diez mil, funcionando como cantidad exacta en comparaciones, recuentos militares o declaraciones proporcionales. Levítico 26:8 lo usa en una proporción precisa: cien pondrán en fuga a diez mil. Jueces 20:10 selecciona diez mil hombres para una operación militar. Deuteronomio 32:30 contrasta uno persiguiendo a mil con dos que hacen huir a diez mil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134374, 'spa', 'mucho, grandemente (adverbial)', 'Uso adverbial mediante el infinitivo absoluto Hifil (60 veces): funciona como intensificador con el sentido de ''mucho, grandemente, en extremo.'' ''Tu galardón será muy grande'' (Gn 15:1) y ''recogió mucho'' (Éx 16:17) muestran la construcción modificando predicados diversos sin ningún sentido de multiplicación numérica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134375, 'spa', 'hacer multiplicar (Hifil)', 'Causativo Hifil, el sentido más frecuente (100 veces): hacer que algo se multiplique, aumentar algo en número. La promesa de Dios ''multiplicaré grandemente tu descendencia'' (Gn 16:10; 17:2; 22:17) convierte a este verbo en la expresión por excelencia de la bendición pactual de crecimiento poblacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134379, 'spa', '¡multiplicaos! (imperativo Qal)', 'Imperativo Qal (7 veces): la orden directa de multiplicarse, concentrada en el mandato creacional y sus renovaciones. ''Fructificad y multiplicaos'' (Gn 1:22, 28; 9:1, 7) establece este como una bendición-mandato divino fundacional, repetida a la familia de Noé después del Diluvio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134381, 'spa', 'multiplicarse, aumentar (Qal)', 'Qal intransitivo (52 veces): llegar a ser muchos, multiplicarse, aumentar por sí mismo. La narrativa de la creación con su ''y se multiplicaron'' (Gn 7:17-18; 8:17) y la explosión demográfica de Israel en Egipto (Éx 1:20) ilustran poblaciones que crecen sin un agente causativo expreso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134405, 'spa', 'engrandecer, magnificar', 'Hifil o Piel que significa engrandecer o magnificar (6 veces): un aumento cualitativo más que cuantitativo — ampliar territorio, magnificar a una persona o expandir influencia. La alabanza de David ''ensanchaste mis pasos'' (2 Sam 22:36 / Sal 18:35) y la oración de Jabés (1 Cr 4:10) ejemplifican este registro elevado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134422, 'spa', 'criar, criar hijos (Piel)', 'Piel intensivo que significa criar o educar hijos (2 veces): un dominio semántico distinto de nutrición y crianza. La metáfora de la leona en Ez 19:2 (''crió a sus cachorros'') y la elegía de Lm 2:22 (''los que crié y engrandecí'') muestran este sentido tierno y parental, muy alejado de la mera multiplicación numérica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134434, 'spa', 'ser grande, ser excesivo (estativo)', 'Qal estativo que describe algo como grande, distante o excesivo (5 veces): el estado de ser demasiado o demasiado extenso. ''El camino es largo para ti'' (Dt 14:24), la porción de José ''fue cinco veces mayor'' (Gn 43:34) y la declaración de Elihú ''Dios es mayor que el hombre'' (Job 33:12) expresan magnitud más que proceso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134516, 'spa', 'Crecer, hacerse grande', 'Crecer, hacerse grande (Qal intransitivo). Usado para el árbol cósmico del sueño de Nabucodonosor que crece alto y poderoso (Dan 4:11, 20), para la grandeza expansiva del propio rey (Dan 4:22) y para su cabello creciendo silvestre durante su exilio bestial (Dan 4:33). El español ''crecer/ha crecido'' traduce consistentemente este crecimiento orgánico e intransitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134520, 'spa', 'Engrandecer, exaltar', 'Engrandecer, magnificar o exaltar a alguien (Piel causativo). Aparece una sola vez en Daniel 2:48, donde el rey ''engrandeció a Daniel'' elevándolo con regalos y autoridad sobre Babilonia. El español ''engrandecer'' captura con precisión el sentido factitivo — causar grandeza en otro — distinguiéndolo claramente del crecimiento intransitivo del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134521, 'spa', 'La capital fortificada de los amonitas, situada a unos 45 kilometros al este del', 'La capital fortificada de los amonitas, situada a unos 45 kilometros al este del rio Jordan. Su designacion completa רַבַּת בְּנֵי עַמּוֹן aparece en 2 Samuel 12:26-27, Deuteronomio 3:11 y Ezequiel 21:25. Tanto en espanol como en ingles se translitера como ''Rabba.'' La ciudad figura prominentemente en las guerras de David y en los oraculos profeticos contra Amon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134528, 'spa', 'grandeza real', 'Grandeza regia que abarca poder político y magnificencia visible. Las cinco apariciones pertenecen a la narrativa cortesana aramea de Daniel. La grandeza de Nabucodonosor es concedida, despojada y restaurada por Dios (Dn 4:22, 36; 5:18-19), convirtiendo el término en una expresión teológicamente cargada de soberanía delegada. Daniel 7:27 transfiere esta grandeza al reino eterno de los santos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134529, 'spa', 'Diez mil, miriada', 'El numeral diez mil o miriada, sinonimo tardio de influencia aramea de רְבָבָה. Se emplea para censos de exiliados (Esd 2:64; Neh 7:66), registros del tesoro del templo (1 Cr 29:7; Esd 2:69), la poblacion de Ninive (Jon 4:11), fuerzas apocalipticas (Dn 11:12) y los veinte mil carros de Dios en forma dual (Sal 68:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134536, 'spa', 'diez mil, miríada', 'La palabra designa el número diez mil, aunque usada hiperbólicamente para multitudes incontables. Daniel 7:10 la emplea en formas tanto Ketiv como Qere—''ribbo'' (Ketiv), ''ribbewan'' (Qere), y nuevamente ''ribbewan''—para describir las miríadas de miríadas que atienden al Anciano de Días en Su trono. La multiplicación de números vastos (''diez mil veces diez mil'') crea un efecto literario de huestes celestiales infinitas, enfatizando la majestad y poder del tribunal divino por medio de números que desafían la comprensión humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134537, 'spa', 'Aguaceros, lluvias copiosas', 'Aguaceros copiosos, lluvia abundante — precipitación torrencial que produce fertilidad, usada literalmente y como metáfora de bendición divina. Dios retiene los aguaceros como disciplina (Jer 3:3) o los envía como provisión (Sal 65:10). Figuradamente, la enseñanza de Moisés cae como lluvia sobre hierba tierna (Deut 32:2), y el remanente de Jacob será como aguaceros entre las naciones (Miq 5:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134543, 'spa', 'El ordinal ''cuarto,'' que indica posición en una secuencia', 'El ordinal ''cuarto,'' que indica posición en una secuencia: cuarto día, cuarto río, cuarto hijo, cuarta generación, cuarto mes, etc. Desde el cuarto río del Edén (Gn 2:14), pasando por la cuarta fila de piedras sacerdotales (Éx 28:20) hasta el cuarto año de reinados (1 R 6:1; Jer 39:2), este es con diferencia el uso más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134544, 'spa', 'Una cantidad fraccionaria que significa ''una cuarta parte de'' una medida estánda', 'Una cantidad fraccionaria que significa ''una cuarta parte de'' una medida estándar, usado en constructo con unidades de medida en regulaciones sacrificiales y cúlticas. Las instrucciones sacerdotales prescriben ''una cuarta parte de un hin'' de aceite (Nm 15:4; 28:5) y ''una cuarta parte de un hin'' de vino (Nm 15:5; 28:7) para diversas ofrendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134554, 'spa', 'Un raro sentido geométrico que significa ''cuadrado,'' describiendo una forma con ', 'Un raro sentido geométrico que significa ''cuadrado,'' describiendo una forma con cuatro lados iguales. En la asignación visionaria de la tierra de Ezequiel, la porción sagrada se describe como ''cuadrada'' (Ez 48:20). Este uso extiende la semántica nuclear de ''cuatro'' de la raíz, desde la secuencia y la fracción hacia la descripción arquitectónica y espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134555, 'spa', 'Cuarto (ordinal arameo)', 'Cuarto: numeral ordinal arameo empleado en las visiones y narraciones de Daniel para señalar un elemento culminante en una serie. El cuarto reino del sueño de Nabucodonosor es fuerte como el hierro y quebranta todo lo demás (Dn 2:40). La cuarta figura en el horno tiene apariencia ''semejante a un hijo de los dioses'', transformando una escena de ejecución en una de liberación divina (Dn 3:25). La cuarta bestia es terrible y poderosa (Dn 7:7, 19, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134560, 'spa', 'bien mezclado (técnico)', 'El término funciona como adjetivo técnico en la ley sacrificial, describiendo harina fina que ha sido completamente mezclada o batida, especialmente con aceite. Levítico 6:21 lo prescribe para la ofrenda de cereal del sumo sacerdote (''bien mezclada, la traerás''), mientras que Levítico 7:12 incluye tortas bien mezcladas con aceite entre las ofrendas de acción de gracias. 1 Crónicas 23:29 enumera la supervisión de ''lo mezclado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134561, 'spa', 'Ribla (toponimo)', 'Nombre propio de una ciudad en Hamat junto al Orontes, cuartel general imperial en la monarquia tardia. Necao detuvo alli a Joacaz (2 R 23:33) y Nabucodonosor la uso como base durante el asedio de Jerusalen (2 R 25:6, 20-21; Jer 39:5-6; 52:9-10, 26-27). Marca ademas el limite nororiental de la tierra prometida (Nm 34:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134565, 'spa', 'jefe de magos (título)', 'Este título cortesano babilónico designa al jefe de los magos o adivinos. Jeremías 39:3 y 39:13 enumeran a ''Nergal-sarezer el Rab-mag'' entre los príncipes babilonios que entraron en Jerusalén después de su caída y se sentaron en la Puerta del Medio. El título indica que este oficial ocupaba un rango elevado en la administración de Nabucodonosor, específicamente sobre la clase de especialistas rituales, adivinos y magos de la corte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134566, 'spa', 'Rab-saris (jefe de eunucos)', 'El titulo compuesto especifico Rab-saris, que designa al jefe de eunucos o principal cortesano de la corte babilonica. En Jer 39:3 y 39:13, el titulo identifica al oficial de Nabucodonosor llamado Nebusazban. El espanol traduce el sentido subyacente como ''eunucos'', mientras que el ingles conserva la transliteracion ''Saris'', reflejando la tension entre transliterar y traducir titulos extranjeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134567, 'spa', 'Jefe, maestro (titulo)', 'El elemento generico de titulo que significa ''jefe'' o ''maestro'', funcionando como primer componente en diversas designaciones compuestas de cargos babilonico-asirios. En 2 Re 18:17 aparece en multiples titulos compuestos durante el asedio asirio de Jerusalen. El espanol ''jefe-de'' capta bien el sentido composicional, mostrando como la palabra sirve como marcador de rango mas que como sustantivo independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134570, 'spa', 'acostarse / aparear', 'El término tiene dos usos distintos pero relacionados. En Salmo 139:3, significa descanso pacífico: ''Conoces mi acostarme'', emparejado con ''mi camino'' para expresar el conocimiento de Dios de todas las actividades, descanso y movimiento. En la legislación de santidad levítica (Levítico 18:23; 19:19; 20:16), denota específicamente el apareamiento animal—prohibiendo a las mujeres ''yacer con'' bestias y prohibiendo el cruce de diferentes especies animales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134571, 'spa', 'Cuadrado, de cuatro lados', 'Hacer cuadrado o de cuatro lados; casi siempre como participio pasivo describiendo objetos sagrados. Se aplica al altar del holocausto (Ex 27:1; 38:1), al altar del incienso (Ex 30:2) y al pectoral del sumo sacerdote (Ex 28:16; 39:9). Ezequiel lo extiende al atrio del templo visionario (Ez 40:47; 43:16; 45:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134575, 'spa', 'Lado, flanco', 'Lado o flanco de una estructura de cuatro lados, siempre en plural precedido de אַרְבַּעַת (''cuatro''). En Ezequiel describe los cuatro lados de los seres vivientes (Ezeq 1:8), sus ruedas que avanzan sin girar (Ezeq 1:17; 10:11), y los cuatro lados del hogar del altar (Ezeq 43:16-17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134576, 'spa', 'Cuarta parte', 'Un cuarto o cuarta parte empleado como unidad fraccional de medida. En Éxodo 29:40, un ''cuarto de hin'' de aceite batido y un ''cuarto de hin'' de vino acompañan la ofrenda de cereal. En 1 Samuel 9:8, el siervo de Saúl tiene ''un cuarto de siclo de plata'' para dar al vidente. El sentido es puramente fraccional y aritmético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134580, 'spa', 'Cuarta generación pactual', 'Designa a quienes pertenecen a la cuarta generación en la fórmula del pacto sobre Dios visitando la iniquidad de los padres ''sobre la tercera y sobre la cuarta'' (עַל־שִׁלֵּשִׁים וְעַל־רִבֵּעִים). Esta frase aparece en Éxodo 20:5 (Decálogo), Éxodo 34:7 (renovación del pacto), Números 14:18 (paciencia divina) y Deuteronomio 5:9 (repetición del Decálogo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134581, 'spa', 'La acción básica en Qal de echarse para descansar o dormir, aplicada tanto a ani', 'La acción básica en Qal de echarse para descansar o dormir, aplicada tanto a animales como a personas que se recuestan en reposo. Los rebaños se echan junto a las piedras del pozo (Gn 29:2), los cachorros de león se tienden tras alimentarse (Gn 49:9), y el justo se acuesta sin temor (Job 11:19). El español ''acostarse'' y ''echarse'' captan fielmente este sentido de reclinarse para el descanso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134584, 'spa', 'El causativo Hifil que significa hacer que alguien o algo se eche, usado predomi', 'El causativo Hifil que significa hacer que alguien o algo se eche, usado predominantemente en contextos pastoriles y de provisión divina. La imagen amada del Salmo 23:2 — ''en verdes pastos me hace recostar'' — ancla este sentido. Jeremías 33:12 y Ezequiel 34:15 lo extienden a Dios restaurando el descanso seguro a su rebaño disperso. El español ''hacer recostar'' y el francés ''faire reposer'' preservan la fuerza causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134585, 'spa', 'La forma participial que describe a una criatura en postura agachada o acostada,', 'La forma participial que describe a una criatura en postura agachada o acostada, frecuentemente con matices de acecho o amenaza. El caso más memorable es Génesis 4:7, donde el pecado está ''agazapado'' (רֹבֵץ) a la puerta como un depredador listo para saltar. También describe a un asno echado bajo su carga (Éx 23:5) e Isacar recostado entre los apriscos (Gn 49:14). El español ''acecha'' capta la connotación de emboscada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134599, 'spa', 'Un uso especializado del Hifil en Isaías 54', 'Un uso especializado del Hifil en Isaías 54:11 que significa asentar o montar piedras firmemente en su lugar, donde Dios promete poner los cimientos de Sion con piedras de antimonio. La fisicalidad central del verbo — presionar algo hacia abajo en una posición fija — se extiende metafóricamente de un cuerpo echado en tierra a una gema engastada en argamasa. El español ''asentaré'' capta este significado orientado a la construcción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134607, 'spa', 'Lugar de reposo', 'Designa un lugar de descanso o guarida donde animales o personas habitualmente se echan. Isaías 65:10 empareja ''lugar de descanso para el ganado'' (רֵבֶץ בָּקָר) con ''aprisco para ovejas'' en imágenes de restauración. Isaías 35:7 menciona la guarida de chacales transformada en pastizal. Jeremías 50:6 usa ''su lugar de descanso'' (רִבְצָם) para Israel como ovejas que olvidaron su redil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134608, 'spa', 'El nombre propio femenino de la esposa de Isaac y madre de Esaú y Jacob, una mat', 'El nombre propio femenino de la esposa de Isaac y madre de Esaú y Jacob, una matriarca central en la historia del pacto de Israel. Presentada a través de su hospitalidad en el pozo (Gn 24:15-67), recibe un oráculo divino sobre dos naciones en su vientre (Gn 25:22-23) y orquesta la obtención de la bendición por parte de Jacob (Gn 27:5-17). Su sepultura en Macpela se menciona en las últimas palabras de Jacob (Gn 49:31). Todas las traducciones preservan el nombre con mínima variación: ''Rebeca'' en español, Rebekka en la Septuaginta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134612, 'spa', 'Grande, imponente', 'Grande o imponente como adjetivo atributivo: tamaño físico (la gran bestia, Dan 7:7), despliegues impresionantes (el banquete de Belsasar, Dan 5:1), magnitud generosa (grandes obsequios, Dan 2:48) o señales poderosas (Dan 4:3). El español ''grandes'' y el inglés ''great'' reflejan este sentido de escala imponente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134613, 'spa', 'Grandes cosas, jactancia', 'Usado como sustantivo para significar ''grandes cosas'', específicamente palabras jactanciosas. En Daniel 7:8, el cuerno pequeño tiene ''una boca que habla grandes cosas'', y en 7:20 pronuncia discursos cuya apariencia supera a sus compañeros. El español ''grandes cosas'' captura este giro sustantival hacia lo presuntuoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134615, 'spa', 'Nobles, magnates cortesanos', 'Nobles, magnates o señores de la corte real: forma reduplicativa aramea intensificada a partir de rav (''grande''), que designa a los funcionarios de más alto rango en la jerarquía imperial babilónica y persa. Uso exclusivo en Daniel: los nobles de Nabucodonosor regresan a él tras su restauración (Dn 4:36), Belsasar banquetea con mil de sus magnates (Dn 5:1) y los señores de Darío están presentes en momentos clave (Dn 6:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134621, 'spa', 'El título militar-diplomático asirio ''jefe de los coperos'' u ''oficial principal,', 'El título militar-diplomático asirio ''jefe de los coperos'' u ''oficial principal,'' que designa al enviado principal de Senaquerib a Jerusalén. En 2 Reyes 18:17-37 e Isaías 36:2-22, este funcionario pronuncia discursos amenazantes en hebreo frente a los muros de Jerusalén, desafiando la confianza de Ezequías en Yahvé. El título es un compuesto de rav (''jefe'') y shaqeh (''copero''), reflejando la jerarquía de la corte asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134627, 'spa', 'El sentido Qal de temblar o estremecerse de miedo o reverencia, el significado d', 'El sentido Qal de temblar o estremecerse de miedo o reverencia, el significado dominante con 26 apariciones. Los pueblos oyen del Éxodo y tiemblan (Éx 15:14); la tierra se estremece ante la presencia de Dios (Sal 99:1; Jl 2:1); toda la ciudad tiembla ante la muerte de Absalón (2 S 18:33). El sujeto puede ser humano o cósmico: naciones, montañas y la tierra misma tiemblan ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134628, 'spa', 'El sentido reflexivo-intensivo del Hitpael', 'El sentido reflexivo-intensivo del Hitpael: enfurecerse violentamente, estar en un estado sostenido de furia. Las 4 apariciones describen el mismo evento en dos relatos paralelos: la arrogante furia del rey asirio contra Dios (2 R 19:27-28 = Is 37:28-29). Dios dice: ''Porque tu furor contra mí ha subido a mis oídos, pondré mi garfio en tu nariz.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134634, 'spa', 'El sentido causativo Hifil de hacer temblar físicamente algo o a alguien, con 4 ', 'El sentido causativo Hifil de hacer temblar físicamente algo o a alguien, con 4 apariciones donde Dios es típicamente el agente que sacude el cosmos. Dios ''sacude la tierra de su lugar'' (Job 9:6); el SEÑOR ''hará estremecer los cielos'' (Is 13:13); el tirano que ''hacía temblar la tierra'' (Is 14:16); el SEÑOR ''sacudió'' a las naciones con la caída de Tiro (Is 23:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134639, 'spa', 'El sentido Qal de agitación emocional, ira o furia dirigida contra alguien, con ', 'El sentido Qal de agitación emocional, ira o furia dirigida contra alguien, con 3 apariciones donde el temblor es de enojo y no de miedo. En Proverbios 29:9 el necio ''se enfurece'' cuando es llevado a juicio; en Isaías 28:21 Dios se levanta con furia ''extraña'' para su obra; en Ezequiel 16:43 Jerusalén ''se enfureció'' contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134644, 'spa', 'Una única aparición Qal en Génesis 45', 'Una única aparición Qal en Génesis 45:24 donde José despide a sus hermanos con la advertencia ''no riñáis por el camino.'' El sentido aquí es disputa o altercado interpersonal: agitación que se exterioriza como conflicto entre personas. Este uso se sitúa en un punto intermedio entre el temblor y la ira, trasladando la agitación interna a una querella externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134646, 'spa', 'El sentido causativo Hifil de perturbar, provocar a ira o causar inquietud a otr', 'El sentido causativo Hifil de perturbar, provocar a ira o causar inquietud a otra persona, con 3 apariciones. Saúl se queja de que Samuel lo ha ''perturbado'' al ser invocado de entre los muertos (1 S 28:15); Job observa que las tiendas de quienes ''provocan a Dios'' están seguras (Job 12:6); Dios no dará ''reposo'' al opresor de Israel (Jer 50:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134665, 'spa', 'Agitación, turbación', 'Agitación interior, turbación emocional e inquietud incesante: la condición perturbada del sufrimiento humano. En Job 3:17 los impíos cesan de su רֹגֶז con la muerte; en 3:26 Job lamenta no tener reposo, solo turbación. Isaías 14:3 lo empareja con dura servidumbre. El español ''turbación'' refleja esta angustia desasosegada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134667, 'spa', 'Ira, furor', 'Ira feroz o furor divino, una fuerza más intensa y activa que la mera ansiedad. El caballo de guerra devora la distancia ''con furor y furia'' (Job 39:24), y Habacuc suplica que Dios recuerde la misericordia ''en la ira'' (Hab 3:2). El español ''ira/furor'' y el inglés ''rage/wrath'' marcan uniformemente esta violencia emocional intensificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134669, 'spa', 'Trueno, estruendo divino', 'El estruendo atronador de la voz de Dios, un sentido meteorológico singular en Job 37:2 donde בְּרֹגֶז קֹלוֹ significa ''en el trueno de Su voz''. El español ''rugido'' capta la potencia casi animal del sonido, mientras que el inglés ''thunder'' y el francés ''agitation'' reflejan el asombro de la imaginería teofánica de la tormenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134672, 'spa', 'Explorar o investigar un lugar secretamente como espía o explorador militar (tro', 'Explorar o investigar un lugar secretamente como espía o explorador militar (tronco Piel). El participio Piel meraggelim (''espías'') predomina, especialmente en la narrativa de José (Gn 42:9, 11, 14, 16, 30) y los relatos de la conquista (Jos 2:1; 6:22-25; 7:2). El español ''espías,'' el francés ''espions'' y el alemán ''Kundschafter'' confirman el sentido de espionaje. También se documenta como infinitivo constructo (leraggel, Nm 21:32) y en los relatos de reconocimiento de Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134676, 'spa', 'Calumniar o difundir informes maliciosos sobre alguien, preservando el sentido e', 'Calumniar o difundir informes maliciosos sobre alguien, preservando el sentido etimológico de ''andar a pie'' con intención malévola. Documentado en el Qal (Sal 15:3, ''no levanta calumnia con su lengua'') y en el Piel (2 S 19:27, la queja de Mefi-boset de que Siba lo calumnió). El español ''calumnió'' y los paralelos semíticos más amplios confirman esta extensión semántica del movimiento físico a la difamación verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134685, 'spa', 'Pie, pies', 'Pie o pies físicos de una figura en visión profética. Las ocho ocurrencias aparecen en Daniel: describe los pies de la estatua de Nabucodonosor (Dan 2:33, 34, 41, 42), cuyos pies de hierro y barro simbolizan un reino frágil, y los pies de bestias temibles (Dan 7:4, 7, 19). El español ''pies'' transmite este único sentido corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134689, 'spa', 'pie (parte del cuerpo)', 'El sentido anatómico primario: el pie físico de un ser humano o animal, con 236 de 251 apariciones, lo que lo hace abrumadoramente dominante. Abarca la hospitalidad del lavamiento de pies (Gn 18:4; 24:32), el mandato sagrado de quitarse las sandalias en suelo santo (Éx 3:5), el rito sacerdotal de aplicar sangre al pie derecho (Lv 8:23) y docenas de usos preposicionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134706, 'spa', 'veces, ocasiones', 'La extensión metonímica a ''veces'' (ocasiones, repeticiones) — 4 apariciones, todas involucrando conteo. En Éx 23:14 se ordena a Israel celebrar ''tres regalim al año,'' las fiestas de peregrinación. En la narrativa de Balaam, la burra se desvía ''tres regalim'' (Nm 22:28, 32, 33). El vínculo conceptual va de pasos repetidos a la idea abstracta de ''ocasiones.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134713, 'spa', 'a pie (peatonal)', 'Uso adverbial que significa ''a pie'' (viaje peatonal) — 4 apariciones donde la frase preposicional funciona como adverbio indicando modo de desplazamiento, en contraste con ir montado. En 2 Sam 15:16-18, la casa de David parte ''a pie'' durante la revuelta de Absalón; el Sal 66:6 recuerda que Israel cruzó el mar ''a pie.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134721, 'spa', 'pierna (miembro inferior)', 'El sentido anatómico extendido: pierna o miembro inferior, no solo el pie. Cuatro apariciones donde la referencia incluye claramente la espinilla, pantorrilla o toda la extremidad inferior. Las grebas de bronce que llegan a las espinillas de Goliat (1 Sam 17:6) y las patas de la mesa del tabernáculo (Éx 25:26; 37:13) usan el vocablo para el miembro completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134736, 'spa', 'paso, marcha', 'Paso, ritmo o forma de caminar — 3 apariciones donde el vocablo denota la manera o velocidad del caminar más que la parte del cuerpo. Jacob le dice a Esaú que viajará ''al paso del ganado'' y ''al paso de los niños'' (Gn 33:14), es decir, acompasándose a su marcha. En Gn 30:30, la riqueza de Labán creció ''a mi paso,'' esto es, al ritmo del trabajo de Jacob.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134788, 'spa', 'Soldado de a pie', 'Soldado de infanteria: hombre que marcha y combate a pie, distinto de conductores de carros y jinetes. Designa a los combatientes de Israel en el Exodo (Ex 12:37; Nm 11:21), la leva tribal en los jueces (Jue 20:2) y los recuentos de tropas en la monarquia (1 S 4:10; 15:4; 2 S 8:4; 2 R 13:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134791, 'spa', 'Apedrear, lapidar — Apedrear o lapidar como forma de ejecución judicial comunal,', 'Apedrear, lapidar — Apedrear o lapidar como forma de ejecución judicial comunal, el único sentido Qal de רָגַם. Prescrito en la ley sacerdotal y deuteronómica para delitos capitales incluyendo blasfemia (Lv 24:14, 16), idolatría (Lv 20:2, 27), quebrantamiento del sábado (Nm 15:35-36) y rebelión filial (Dt 21:21). En la narrativa aparece en la ejecución de Acán (Jos 7:25), el apedreamiento de Adoram (1 Re 12:18; 2 Cr 10:18) y las amenazas de la congregación contra Moisés (Nm 14:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134808, 'spa', 'murmurar / calumniar', 'La palabra captura tanto la murmuración rebelde contra Dios como el chisme malicioso sobre personas. Deuteronomio 1:27 y Salmo 106:25 recuerdan la murmuración infiel de Israel en sus tiendas durante la peregrinación del desierto—quejas descontentas sobre el liderazgo de Dios. Isaías 29:24 describe murmuradores que aprenderán doctrina, sugiriendo resistencia escéptica a la enseñanza. Mientras estos usos enfatizan el descontento rebelde, Proverbios 16:28 y 26:20 emplean el participio para ''chismosos'' que siembran discordia mediante calumnias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134809, 'spa', 'En un instante (Hifil)', 'Actuar en un instante, de repente, en un momento (Hifil denominativo de rega''). En Prov 12:19 la lengua mentirosa dura solo ''un pestanear'', contrastada con la verdad establecida para siempre. En Jer 49:19 y 50:44, Dios declara ''en un momento los hare huir'', enfatizando la aterradora rapidez del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134811, 'spa', 'Agitar, perturbar (Qal)', 'Agitar, remover o perturbar, especialmente el mar y sus olas (participio activo Qal). Isa 51:15 y Jer 31:35 usan la frase identica: Dios es ''el que agita el mar para que bramen sus olas''. Es un titulo de soberania cosmica: el Creador que gobierna las profundidades caoticas. El espanol ''el que agita'' preserva la agencia divina activa del original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134813, 'spa', 'Aquietar, calmar (Qal)', 'Aquietar o calmar el mar (Qal perfecto), aparentemente lo opuesto al sentido 2 pero expresando el mismo dominio divino. En Job 26:12, ''con su poder aquieto el mar'' aparece junto al golpe contra Rahab, describiendo la victoria de Dios sobre el caos. Algunos estudiosos sugieren que la raiz porta un sentido neutro que el contexto especifica como agitacion o calma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134814, 'spa', 'Dar descanso, reposar', 'Estar en reposo o causar descanso; en Nifal ''estate quieto, reposa'' (Jer 47:6), en Hifil ''dar descanso a'' (Jer 31:2; 50:34). El espanol ''descansaras'' y ''para darle descanso'' captan el rango desde el reposo intransitivo hasta el otorgamiento causativo de paz. Deut 28:65 usa la forma negativa — Israel no hallara reposo — intensificando la advertencia del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134818, 'spa', 'Establecer, asentar firmemente', 'Establecer o asentar algo firmemente en su lugar, un uso especializado del Hifil en Isa 51:4, donde Dios declara ''establecere mi justicia como luz para los pueblos''. El espanol ''establecere'' distingue esto del mero descanso, apuntando hacia una fundacion permanente. Este sentido extiende la metafora de la raiz: lo verdaderamente en reposo es lo fijado en su lugar propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134821, 'spa', 'Un momento o breve lapso de tiempo usado como sustantivo temporal — ''un momento,', 'Un momento o breve lapso de tiempo usado como sustantivo temporal — ''un momento,'' ''cada momento,'' ''por un breve instante.'' Se encuentra en expresiones que describen la paciencia divina (Job 7:18, ''a cada momento lo pruebas''), la brevedad de la ira divina frente al favor duradero (Sal 30:5), y la naturaleza fugaz de la prosperidad de los malvados (Job 20:5). El español ''instante'' y el francés ''instant'' reflejan fielmente este sentido temporal compacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134822, 'spa', 'Un uso adverbial que expresa lo repentino o instantáneo, típicamente con preposi', 'Un uso adverbial que expresa lo repentino o instantáneo, típicamente con preposición (בְּרֶגַע ''en un momento,'' כְּרֶגַע ''como un momento''). Este sentido predomina en contextos de acción divina fulminante — la congregación podría ser consumida ''en un instante'' (Nm 16:21, 45), los malvados perecen súbitamente (Job 21:13; 34:20), y los enemigos son avergonzados ''en un instante'' (Sal 6:10). El paso de la duración a la puntualidad marca una distinción adverbial clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134835, 'spa', 'reunirse tumultuosamente', 'El término captura la asamblea agresiva y urgente de un grupo con intención. Las tres apariciones en Daniel 6 (versículos 6, 11, 15) describen a los oficiales, sátrapas y gobernadores ''viniendo en tropel'' al rey—primero para proponer el decreto irrevocable, luego para acusar a Daniel, finalmente para exigir su cumplimiento. El verbo sugiere no deliberación tranquila sino urgente presión desordenada—una acción similar a una turba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134838, 'spa', 'Someter y batir metal', 'Expresa abatimiento o subyugación tanto en contextos militares como artesanales. El infinitivo Qal en Isaías 45:1 describe someter naciones ante Ciro; el Salmo 144:2 usa el participio ''el que somete a mi pueblo bajo mí''. En 1 Reyes 6:32, el Hifil significa ''batir oro'' sobre los querubines, martillando láminas delgadas de oro para recubrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134839, 'spa', 'Pisotear, aplastar o raspar — una raíz homógrafa distinta (רדה II)', 'Pisotear, aplastar o raspar — una raíz homógrafa distinta (רדה II). Jueces 5:13 la usa para describir al remanente ''pisoteando'' a los poderosos, y Lamentaciones 1:13 describe el fuego enviado a los huesos que los ''dominó.'' El francés ''descendit'' y el español ''bajó'' revelan que los traductores leyeron un movimiento físico descendente en lugar de autoridad política. Algunos lexicógrafos conectan este sentido con el raspar la miel de Jueces 14:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134840, 'spa', 'Gobernar, ejercer dominio o autoridad sobre personas, criaturas o territorio', 'Gobernar, ejercer dominio o autoridad sobre personas, criaturas o territorio. Génesis 1:26-28 establece el mandato de la creación; el Salmo 72:8 contempla al Mesías gobernando de mar a mar; 1 Reyes 5:4 describe el dominio de Salomón. Levítico 25:43, 46, 53 restringe esta autoridad: Israel no debe gobernar con dureza a sus hermanos. El español ''dominar'' y ''señorear'' reflejan fielmente la fuerza soberana de este sentido principal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134854, 'spa', 'Someter o sojuzgar por la fuerza coercitiva — una intensificación que va más all', 'Someter o sojuzgar por la fuerza coercitiva — una intensificación que va más allá de la gobernación normal. Isaías 41:2 pregunta quién levantó a uno del oriente y lo ''hace gobernar'' (yirdennu) sobre reyes, con el español ''sojuzga'' y el sentido árabe de pisoteo violento subrayando el carácter militar que distingue este sentido del dominio ordenado del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134861, 'spa', 'Raspar, extraer', 'El término describe la acción de raspar algo para sacarlo de una superficie. En Jueces 14:9, Sansón ''raspó'' la miel del cuerpo del león muerto y ''la raspó en sus palmas'', enfatizando el acto físico de extraer el panal de una fuente inesperada. La interpretación propuesta en Jeremías 5:31, donde los profetas ''gobiernan'' o quizás ''raspan ganancia'' con sus manos, encajaría en este mismo campo semántico de extracción o remoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134864, 'spa', 'Caer en sueño profundo', 'Caer o estar en un sueño profundo y pesado cercano a la inconsciencia, ya sea por agotamiento (Jue 4:21; Jon 1:5), abrumamiento divino (Dan 8:18; 10:9) o el sueño figurativo de la muerte (Sal 76:7). El cognado árabe radama (''tapar, obstruir'') sugiere estar ''sellado'' de la conciencia vigil. El español ''caer en sueño profundo'' enfatiza su profundidad e involuntariedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134871, 'spa', 'perseguir, dar caza (Qal)', 'El significado nuclear del Qal, que abarca 119 de 144 apariciones: perseguir físicamente a una persona o grupo para alcanzarlos. Génesis 14:14 tiene a Abram persiguiendo a los captores de Lot; Éxodo 14:8-9 describe al ejército de Faraón persiguiendo a Israel. Un sentido directo de persecución militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134875, 'spa', 'perseguir con ahínco (Piel)', 'La intensificación del Piel transmite una persecución tenaz y sostenida — no una sola cacería sino un seguimiento persistente. Proverbios emplea esta conjugación para perseguir la justicia (11:19) o cosas vanas (12:11). El coreano chugu (추구) capta bien esta cualidad determinada y continua, distinta de la persecución puntual del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134893, 'spa', 'perseguir, hostigar', 'Persecución con intención hostil de hacer daño, especialmente al inocente o al justo. Los Salmos concentran este sentido: ''mis perseguidores'' (Sal 119:84, 86, 157) enmarca el sufrimiento bajo un poder injusto. Los traductores distinguen consistentemente este peso teológico del mero perseguir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134903, 'spa', 'seguir, buscar (abstracto)', 'Búsqueda abstracta de un objetivo o ideal más que de una persona. ''Persigue la justicia'' (Dt 16:20), ''busca la paz'' (Sal 34:14), ''la bondad y la misericordia me seguirán'' (Sal 23:6). Una extensión metafórica de la imagen de la persecución: aspiración, no agresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134927, 'spa', 'ser perseguido (Nifal)', 'El pasivo Nifal: ser objeto de persecución o acoso. Eclesiastés 3:15 dice que Dios busca lo que ha sido perseguido (lo ahuyentado), y Lamentaciones 5:5 lamenta ''somos perseguidos.'' La voz pasiva se confirma en las tradiciones de traducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134942, 'spa', 'perseguir y aplastar', 'Una aparición singular en Jueces 20:43 donde la persecución implica rodear y pisotear — el impacto físico de alcanzar a los benjaminitas en fuga. El dominio se desplaza del mero movimiento lineal al contacto violento al dar alcance, como lo muestran las glosas que aun así traducen ''lo persiguieron.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134959, 'spa', 'ser arrojado, aventado', 'En Isaías 17:13, un uso pasivo o resultativo: la paja ''es perseguida'' delante del viento. Esta aparición singular capta la imagen de ser arrojado como escombros aventados por el viento, una vívida metáfora del juicio divino que dispersa a las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134964, 'spa', 'Acción violenta y turbulenta', 'Expresa una acción enérgica y tempestuosa que varía según el contexto. En Isaías 3:5, el joven «arremete contra» (יִרְהֲבוּ) el anciano en medio del caos social. Proverbios 6:3 aconseja «importuna» (רְהַב) a tu prójimo para librarte de la fianza. En Cantares 6:5, los ojos de la amada «me abruman» (הִרְהִיבֻנִי), posiblemente causando sobrecogimiento, aunque el texto es incierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134965, 'spa', 'Monstruo mítico; Egipto', 'Este nombre mitológico designa tanto un monstruo marino primordial como, simbólicamente, Egipto. Job 9:13 y 26:12 emplean Rahab en lenguaje de creación: Dios somete ''a los ayudadores de Rahab'', paralelo a aplastar el mar y traspasar la serpiente, reflejando imágenes cosmológicas antiguas de victoria divina sobre el caos. Isaías 30:7 hace explícita la transición simbólica: Egipto es llamado Rahab, pero ''Rahab que se queda quieta'', impotente para actuar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134966, 'spa', 'Monstruo del caos', 'El término funciona como nombre propio de una criatura marina mítica que encarna el caos y la oposición al orden divino. Salmo 89:10 usa imágenes violentas: ''Tú aplastaste a Rahab como a uno de los muertos'', celebrando la victoria de Dios. Salmo 87:4 lista a Rahab (Egipto) junto con Babilonia como naciones que reconocerán a Sion. Isaías 51:9 hace la conexión más explícita: ''¿No fuiste tú quien cortó a Rahab en pedazos, quien traspasó al dragón?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134970, 'spa', 'Abrevadero', 'El término identifica las estructuras o canales usados para dar agua al ganado en contextos pastorales. En Génesis 30:38 y 41, Jacob estratégicamente coloca varas descortezadas ''en los abrevaderos'' donde los animales más fuertes venían a beber, implementando su esquema de reproducción selectiva. Éxodo 2:16 describe a las siete hijas de Jetro llenando ''los abrevaderos'' para dar agua a las ovejas de su padre antes de que los pastores egipcios las echaran.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134973, 'spa', 'Movimiento errante e inquieto', 'Capta un movimiento inquieto o libre. En Jeremías 2:31, Israel dice «vagamos libremente» (רַדְנוּ), afirmando su independencia de Dios. El Salmo 55:2 expresa «estoy inquieto» (אָרִיד) en queja y lamento. Génesis 27:40 promete a Esaú que «cuando te agites» (תָּרִיד), se librará del yugo de Jacob. Oseas 12:1 presenta un texto corrupto de difícil interpretación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134974, 'spa', 'Beber hasta saciarse, estar saciado, banquetear hasta la satisfaccion', 'Beber hasta saciarse, estar saciado, banquetear hasta la satisfaccion. Sentido intransitivo basico del Qal: haber tenido suficiente. El Salmo 36:8 describe a los justos banqueteando de la abundancia de la casa de Dios; Proverbios 7:18 lo usa para amantes que beben hasta saciarse de pasion; Jeremias 46:10 describe una espada saciada de sangre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134975, 'spa', 'Empapar, regar abundantemente o saturar', 'Empapar, regar abundantemente o saturar. Piel intensivo con sentido fisico y agricola. El Salmo 65:10 celebra a Dios regando los surcos de la tierra y asentando sus terrones; Isaias 34:7 describe el suelo empapado de sangre. El enfoque esta en el material que se satura -- suelo, tierra, campo -- mas que en las personas.');